     *
     * @param array $args Arguments de mise en page, comme le titre, la classe et id HTML.
     * @param array $instance Données du widget.
     */
    public function widget( $args, $instance ) {

        // Parcourir les derniers articles publiés sous le nouveau type de publication personnalisé.
        $args = array(
            'post_type' => 'mon_post_type',
            'posts_per_page' => 3, // Afficher 3 derniers articles
        );

        $query = new WP_Query( $args );

        if ( $query->have_posts() ) :

            echo $args['before_widget'];

            echo '<ul>';

            while ( $query->have_posts() ) : $query->the_post();

                // Afficher les éléments que vous souhaitez, par exemple, le titre de l'article.
                echo '<li><a href="' . Get_post_permalink() . '">' . Get_the_title() . '</a></li>';

            endwhile;

            echo '</ul>';

            echo $args['after_widget'];

            wp_reset_postdata();

        endif;

        wp_reset_query();
    }
