@SpringBootTest(classes = InvoiceManagementApplication.class)
@AutoConfigureMockMvc
@TestPropertySource(locations = "classpath:application-test.properties")
public class InvoiceManagementTest {

    @Autowired
    private DataSource dataSource;

    @Autowired
    private MockMvc mockMvc;

    @DataProvider
    public static Object[][] generateInvoiceData() {
        Faker faker = new Faker();
        return new Object[][] {
                {"INV-0001", faker.company().name(), faker.number().digits(2).randomDouble(2, 0, 1000)},
                {"INV-0002", faker.company().name(), faker.number().digits(2).randomDouble(2, 0, 1000)}
        };
    }

    @Given("a valid Oracle EBS client connection")
    public void setupDb() {
        // Configuration et connexion à la base de données Oracle EBS
    }

    @Given("the following invoice data:")
    @UseDataProvider("generateInvoiceData")
    public void provideInvoiceData(String invoiceNumber, String customerName, Double amount) {
        // Création des données de factures générées par la bibliothèque DataFaker
    }

    @When("I make a POST request to the '/invoices' REST endpoint")
    public void makeInvoicePostRequest() throws Exception {
        this.mockMvc.perform(
                MockMvcRequestBuilders.post("/invoices")
                        .contentType("application/json")
                        .content("{}", InvoiceJsonConverter.toJson(new Invoice(invoiceNumber, customerName, amount))),
                "/invoices");
    }

    @Then("a new invoice should have been created in Oracle EBS")
    public void confirmInvoiceCreated() {
        // Vérification de l'insertion de données dans la base de données Oracle EBS
        Assertions.assertThat(this.dataSource.getConnection().createStatement().executeQuery("SELECT invoice_number FROM ar_invoices WHERE invoice_number = '" + invoiceNumber + "'").next()).isTrue();
    }

    @Then("the invoice number should be equal to the provided invoice_number")
    public void confirmInvoiceNumber() {
        // Vérification de la correspondance du numéro de facture dans la base de données Oracle EBS
        Assertions.assertThat(this.dataSource.getConnection().createStatement().executeQuery("SELECT invoice_number FROM ar_invoices WHERE invoice_number = '" + invoiceNumber + "'").next().getString("invoice_number")).isEqualTo(invoiceNumber);
    }

    @Then("the customer name should be equal to the provided customer_name")
    public void confirmCustomerName() {
        // Vérification de la correspondance du nom du client dans la base de données Oracle EBS
        Assertions.assertThat(this.dataSource.getConnection().createStatement().executeQuery("SELECT customer_name FROM ar_customers WHERE name = '" + customerName + "'").next().getString("customer_name")).isEqualTo(customerName);
    }

    @Then("the amount should be equal to the provided amount")
    public void confirmAmount() {
        // Vérification de la correspondance de la somme dans la base de données Oracle EBS
        Assertions.assertThat(this.dataSource.getConnection().createStatement().executeQuery("SELECT amount FROM ar_invoices WHERE invoice_number = '" + invoiceNumber + "'").next().getDouble("amount")).isEqualTo(amount);
    }

    private static class Invoice {

        private final String invoiceNumber;
