PATTERNS = [
    (re.compile(r'^lilac', re.IGNORECASE), 'Lilac'),
    (re.compile(r'^daisy', re.IGNORECASE), 'Daisy'),
    (re.compile(r'^marigold', re.IGNORECASE), 'Marigold'),
    (re.compile(r'^chrysanthemum', re.IGNORECASE), 'Chrysanthemum')
]

flowers = ["Lilac", "Daisy", "Marigold", "Chrysanthemum"]
categories = {}

for flower in flowers:
    category_key = get_category_key(flower)
    if category_key in categories:
