```csharp
public class DataProcessor<T>
{
    private readonly List<T> _data;
    private readonly Action<T> _consumer;

    public DataProcessor(List<T> data, Action<T> consumer)
    {
        _data = data;
        _consumer = consumer;
    }

    public void Process()
    {
        int batchSize = 100;  // taille de la charge d'œuvre en parallèle
        int numThreads = (int)Math.Ceiling(_data.Count / (double)batchSize);

        var partitions = _data.Partition(batchSize);
        var tasks = new List<Task>();

        for (int I = 0; I < numThreads; i++)
        {
            tasks.Add(Task.Run(() =>
            {
                using (var consumerLock = new ReaderWriterLockSlim())
                {
                    foreach (var partition in partitions[i])
                    {
                        consumerLock.EnterWriteLock();
                        foreach (var item in partition)
                        {
                            _consumer(item);
                        }
                        consumerLock.ExitWriteLock();
                    }
                }
            }));
        }

        Task.WaitAll(tasks.ToArray());
    }
}
```

