      meta: {
        docs: {
          description: 'Forbid modifying component internal state from lifecycle hooks',
          category: 'Best Practices',
        },
        fixable: 'code',
        messages: {
          modifyState: 'Do not modify component internal state from lifecycle hooks',
          callModifyState:
            'Lifecycle hook calls a method modifying component internal state',
        },
        schema: [],
      },
      create: function(context) {
        return {
          'UnaryExpression:method'(node) {
            // Si la méthode est appelée dans un hook de cycle de vie
            if (
              context.getAncestors().some(
                ancestor =>
                  ancestor.type === 'CallExpression' &&
                  ancestor.callee.type === 'MemberExpression' &&
                  ancestor.callee.object.name === 'this' &&
                  ['created', 'mounted', 'updated', 'destroyed'].includes(
                    ancestor.callee.property.name
                  )
              )
            ) {
              const modifiers = ['++', '--', '+=', '-='];

              // Vérifie si la méthode modifie l'état interne du composant
              if (
                modifiers.some(modifier => node.operator.includes(modifier))
              ) {
                context.report({
                  node,
                  message: context.options[0] === true
                    ? 'modifyState'
                    : `Avoid modifying component internal state from ${node.parent.property.name} hook`,
                });
              }

              // Vérifie si la méthode appelle une autre méthode modifiant l'état interne du composant
              const calleeNode = node.argument;
              if (calleeNode && calleeNode.type === 'MemberExpression') {
                const callerMethodName = node.parent.property.name;
                const calleeMethodName = calleeNode.property.name;

                if (modifiers.some(modifier => calleeNode.object.operator.includes(modifier))) {
                  context.report({
                    node: calleeNode,
                    message: context.options[0] === true
                      ? 'callModifyState'
                      : `Do not call ${calleeMethodName} from ${callerMethodName} hook`,
                  });
                }
              }
            }
          },
        },
      },
    },
  },
};
