    meta: {
      docs: {
        description: `Vérifie si les hooks de cycle de vie d'un composant Vue.js ne modifient pas directement l'état interne du composant et appellent également d'autres méthodes qui le font.`,
      },
    },
    create: function(context) {
      const Vue = context.parser.currentScope.Vue;
      const scope = context.getScope();
      const componentScopedVariables = scope.variableDeclarations.native || [];

      return {
        'CallExpression'(node) {
          const { callee } = node;

          // vérification de chaque hook de cycle de vie
          if (
            VueLifecycleHooks.has(callee.property.name) ||
            VueLifecycleHooks.has(callee.object.name)
          ) {
            const targetVariable = findComponentScopedVariable(callee, componentScopedVariables);

            if (targetVariable) {
              // vérification de la méthode appelée modifiant l'état interne du composant
              if (IsMutableMethod(node.arguments[0].name)) {
                context.report({
                  node,
                  message: `La méthode ${node.arguments[0].name} modifie l'état interne du composant dans le hook-cycle de vie "${callee.property.name}"`,
                });
              }

              // vérification d'appels de méthodes qui modifient l'état interne du composant
              const argumentsNodes = node.arguments || [];
              argumentsNodes.forEach(argumentNode => {
                if (IsMethodCall(argumentNode) && IsMutableMethod(argumentNode.callee.name)) {
                  context.report({
                    node: argumentNode,
                    message: `La méthode appelée ${argumentNode.callee.name} modifie l'état interne du composant`,
                  });
                }
              });
            }
          }
        },
      };
    },
  },
};

const VueLifecycleHooks = {
  beforeCreate: true,
  created: true,
  beforeMount: true,
  mounted: true,
  beforeUpdate: true,
  updated: true,
  activated: true,
  deactivated: true,
  beforeDestroy: true,
  destroyed: true,
  errorCaptured: true,
};

function findComponentScopedVariable(callee, componentScopedVariables) {
  // recherche une variable locale du composant qui est utilisée dans la méthode appelée
  const targetVariable = componentScopedVariables.find(variable => variable.id.name === callee.property.name);

  // si une correspondance est trouvée, vérifie son type d'accès
  if (targetVariable) {
    const { typeAnnotation } = targetVariable.def.value;

    if (typeAnnotation && typeAnnotation.type === 'TSUnionType') {
      const types = typeAnnotation.types;

      return types.find(type => type.type === 'TSTypeReference' && type.unit.name === 'Data')?.name;
    }

    return targetVariable.id.name;
  }

  return null;
}

function IsMutableMethod(methodName) {
  return Vue.prototype[methodName] && Vue.prototype[methodName].length === 2 && Vue.prototype[methodName].includes('set');
}
