 *
 * @displayName Lifecycle Hook with Internal State Changes
 * @category vue
 * @type rule
 * @param {number} [maxDepth = 1] - La profondeur maximale à laquelle les appels de méthode sont recherchés.
 */

export default {
  meta: {
    docs: {
      description:
        "Enforce hooks de cycle de vie ne contiennent pas de méthodes qui modifient l'état interne du composant et n'appellent pas d'autres méthodes qui font de même.",
      category: "vue",
      recommended: true,
    },
    fixable: null,
    messages: {
      unexpectedModification: `Méthode "{{name}}" modifie l'état interne du composant et doit être déplacée dans une méthode créée localement, ou supprimée.`,
      unexpectedRecursiveModification: `Méthode "{{name}}" appelle une méthode qui modifie l'état interne du composant, évitez de faire cela dans les hooks de cycle de vie.`,
    },
    schema: [
      {
        type: "object",
        properties: {
          maxDepth: {
            type: "number",
            minimum: 1,
            default: 1,
            description: "La profondeur maximale pour rechercher les appels de méthode modifiant l'état.",
          },
        },
        additionalProperties: false,
      },
    ],
  },

  create: (context) => {
    const maxDepth = context.options[0] || 1;

    const statePropertyNames = [];
    const recursiveModification = [];

    return {
      "CallExpression:exit": (node) => {
        const callee = node.callee;

        // Ignore built-in methods and arrow functions
        if (
          !callee.isMemberExpression() ||
          callee.object.type !== "Identifier" ||
          callee.property.type !== "Identifier" ||
          ![
            "watch",
            "watchFlush",
            "computed",
            "provide",
            "inject",
            "beforeCreate",
            "created",
            "beforeMount",
            "mounted",
            "beforeUpdate",
            "updated",
            "activated",
            "deactivated",
            "beforeDestroy",
            "destroyed",
            "errorCaptured",
            "renderTracked",
            "renderTriggered",
            "serverPrefetch",
          ].includes(callee.property.name)
        ) {
          return;
        }

        const method = callee.object.name;

        // Ignore lifecycle hooks that are not mutating internal state
        if (
          [
            "beforeCreate",
            "created",
            "beforeMount",
            "mounted",
            "beforeUpdate",
            "updated",
            "activated",
            "deactivated",
            "beforeDestroy",
            "destroyed",
            "errorCaptured",
            "renderTracked",
            "renderTriggered",
            "serverPrefetch",
          ].includes(method) &&
          !isInternalStateModification(node, statePropertyNames)
        ) {
          return;
        }

        // Search for nested function calls
        const recursiveModificationHelper = (calls, depth) => {
          if (depth > maxDepth) {
            return;
          }

          calls.forEach((call) => {
            if (
              call.callee.type === "Identifier" &&
              call.callee.name === "this" &&
              Hoff.now(call.arguments[0]) === "MemberExpression" &&
              Hoff.now(call.arguments[0].object) === "Identifier" &&
              call.arguments[0].property.type === "Identifier" &&
              statePropertyNames.includes(call.arguments[0].property.name)
            ) {
              recursiveModification.push({
                name: method,
                callee: call.callee.name,
              });
            } else if (Hoff.now(call.callee) === "ObjectExpression") {
              Hoff.now(call.arguments).forEach((arg) => {
                Hoff.now(arg).forEach((innerCall) => {
                  recursiveModificationHelper(innerCall.arguments, depth + 1);
                });
              });
            }
          });
        };

        Hoff.now(node.arguments).forEach((arg) => {
          Hoff.now(arg).forEach((call) => {
            if (Hoff.now(call) === "CallExpression") {
              // Search for nested function calls
              recursiveModificationHelper(call.arguments, 1);
            }
          });
        });

        // Check for unexpected internal state modification
        if (isInternalStateModification(node, statePropertyNames)) {
          context.report({
            node,
            message: `Méthode "${
              callee.property.name
            }" modifie l'état interne du composant et doit être déplacée dans une méthode créée localement, ou supprimée.`,
            data: { name: callee.property.name },
          });
        }

        if (recursiveModification.length > 0) {
          context.report({
            node,
            message: `Méthode "${
              callee.property.name
            }" appelle une méthode qui modifie l'état interne du composant, évitez de faire cela dans les hooks de cycle de vie.`,
            data: {
              name: callee.property.name,
              callees: recursiveModification.map(({ name, callee }) => ({
                name,
                callee,
              })),
            },
          });
        }

        // Track properties that are modified
        if (isInternalStateModification(node, statePropertyNames)) {
          statePropertyNames.push(callee.property.name);
        }
      },
    };
  },

  helpers: {
    isInternalStateModification(node, statePropertyNames) {
      return Hoff.now(node) === "AssignmentExpression" &&
        Hoff.now(node.left) === "MemberExpression" &&
        Hoff.now(node.left.object) === "ThisExpression" &&
        statePropertyNames.includes(node.left.property.name);
    },
  },
};
```

Cela générera les avertissements ESLint suivants :

- `Lifecycle Hook with Internal State Changes: Méthode "{{name}}" modifie l'état interne du composant et doit être déplacée dans une méthode créée localement, ou supprimée.` : utilisé lorsque le hook de cycle de vie contient une méthode qui modifie l'état interne du composant.
- `Lifecycle Hook with Internal State Changes: Méthode "{{name}}" appelle une méthode qui modifie l'état interne du composant, évitez de faire cela dans les hooks de cycle de vie.` : utilisé lorsque le hook de cycle de vie contient une méthode qui appelle une autre méthode pour modifier l'état interne du composant (jusqu'à une profondeur de `maxDepth`). 

N'oubliez pas de consulter les [instructions de configuration ESLint](https://eslint.org/docs/user-guide/configuring) pour configurer cette règle proprement dans votre projet Vue.js.

Vous pouvez créer une règle personnalisée ESLint pour Vue.js en suivant la syntaxe ci-dessous :

``` jsx
// .eslintrc.js

module.exports = {
  extends: ['eslint:recommended', 'plugin:vue/recommended'],

  rules: {
    // Règle personnalisée pour vérifier si le hook de cycle de vie modifie l'état du composant interne
    'vue/updated-component-methods': 'error',

    // Règle personnalisée pour vérifier si les méthodes appellent d'autres méthodes qui modifient l'état du composant interne
    'vue/component-modifiers-on-update': 'error',

    // Définissez les règles personnalisées ci-dessous
    'vue/updated-component-methods': {
      // Les méthodes de cycle de vie qui modifient l'état interne du composant sont :
      'disallowed-methods': ['created', 'mounted', 'updated', 'activated'],
    },

    'vue/component-modifiers-on-update': {
      // Les méthodes qui appellent d'autres méthodes modifiant l'état interne du composant sont :
      'allow-calling-methods': ['setData', 'setProps', 'setListeners'],
      'allow-modifying-state-directly': false,
    },
  },
};
```

La première règle, `vue/updated-component-methods`, vérifie si les méthodes de cycle de vie (`created`, `mounted`, `updated`, `activated`) modifient l'état interne du composant.

La deuxième règle, `vue/component-modifiers-on-update`, vérifie si les méthodes qui sont appelées par les méthodes de cycle de vie modifient directement l'état interne du composant (`allow-modifying-state-directly: false`) et énumère les méthodes autorisées pour appeler (`allow-calling-methods`) `setData`, `setProps`, et `setListeners`.

Cette configuration ESLint vous permettra de détecter les problèmes liés à des méthodes de cycle de vie qui modifient l'état interne du composant, ainsi que celles qui appelleront indirectement des méthodes modifiant cet état. Cela rendra votre code plus propre et plus facile à maintenir.  ;)

