const modifierKeywords = ['assign', 'delete', 'get', 'set'];
const internalBindings = ['this'];

function isAssignmentExpression(node) {
  return node.operator == '=' && node.left.type === 'MemberExpression';
}

function getLeftMemberExpression(node) {
  return node.left;
}

function isStateModifierExpression(node) {
  // Modifiez les mots-clés suivants pour correspondre à votre propre convention de noms de fonctions modifiant l'état
  return (
    modifierKeywords.some((keyword) => node.left.object.property.name?.includes(keyword)) ||
    (node.left.property && node.left.property.name?.startsWith('$')) ||
    (node.right && node.right.type === 'MemberExpression' &&
      modifierKeywords.some((keyword) => node.right.object.property.name?.includes(keyword)) ||
      (node.right.object && node.right.object.name === 'this' && internalBindings.includes(getBindingIdentifier(node.right.object)))
    )
  );
}

function checkMethodForStateModifications(callExpression, parent) {
  const callee = callExpression.callee;

  if (callee.type === 'MemberExpression' && callee.object.type === 'ThisExpression') {
    const methodName = callee.property.name;

    // vous pourriez ajouter d'autres fonctions modifiant l'état ici, selon votre convention de noms
    if (methodName === 'data' || methodName === 'props' || methodName === 'computed' || methodName === 'watch') {
      const { arguments: callArgs } = callExpression;
      const methodArgs = callArgs.map((arg) => {
        if (arg.type === 'ObjectExpression') {
